function preview(p){return `<div class="preview-art" role="img" aria-label="Illustrative layout concept for ${esc(p.title)}"><div class="preview-nav">⌂<br>Overview<br>Records<br>Calendar<br>Reports</div><div class="preview-content"><strong>${p.id==='home-budget'?'Home Budget Dashboard':esc(p.title)}</strong><div class="preview-metrics">${p.id==='home-budget'?'<span>Monthly Income<br><b>$4,800</b></span><span>Total Expenses<br><b>$3,265</b></span><span>Remaining<br><b>$1,535</b></span>':'<span>Monthly overview<br><b>Sample data</b></span><span>Progress<br><b>Planning</b></span><span>Summary<br><b>Concept</b></span>'}</div><div class="preview-charts"><div class="bars">${[38,70,48,85,58,94,75].map(n=>`<i style="height:${n}%"></i>`).join('')}</div><div class="pie"></div></div><small>Illustrative preview · product not yet tested</small></div></div>`}
function card(p){if(p.id==='lake-house-at-sunset')return "<article class=\"catalog-card\" data-search=\"lake house at sunset browser start page editable links categories home open theory cove\" data-cat=\"open-theory-cove\" data-type=\"Finished HTML\"><a href=\"/lake-house-at-sunset.html\"><img src=\"data:image/jpeg;base64,\" alt=\"Lake House at Sunset cabin and mountain lake artwork\" style=\"display:block;width:100%;aspect-ratio:3/2;object-fit:cover\"></a><div class=\"catalog-copy\"><span class=\"pill\">OPEN THEORY COVE · FINISHED DIGITAL PRODUCT</span><h2><a href=\"/lake-house-at-sunset.html\">Lake House at Sunset</a></h2><p>A warm, scenic browser home page with 12 editable categories, 105 starter links, a live local clock, and simple backup tools.</p><p>HTML start page + setup guides in one portable ZIP.</p><a class=\"btn outline\" href=\"/lake-house-at-sunset.html\">View product →</a><p><small>Purchasing opens soon.</small></p></div></article>";return `<article class="catalog-card" data-search="${esc((p.title+' '+p.desc).toLowerCase())}" data-cat="${p.cat}" data-type="${p.type}"><div class="mini-art">${preview(p)}</div><div class="catalog-copy"><span class="pill">PLANNED · ${p.type.toUpperCase()}</span><h2><a href="/${p.cat}.html?product=${p.id}">${p.title}</a></h2><p>${p.desc}</p><p class="price">Proposed price: $${p.price}</p><a class="btn outline" href="/${p.cat}.html?product=${p.id}">Explore project →</a></div></article>`}
