document.querySelector('.menu-toggle').onclick=function(){const open=document.querySelector('#nav').classList.toggle('open');this.setAttribute('aria-expanded',open);this.setAttribute('aria-label',open?'Close navigation':'Open navigation')};
document.querySelectorAll('.dropbtn').forEach(b=>b.onclick=()=>{const open=!b.parentElement.classList.contains('open');document.querySelectorAll('.drop').forEach(d=>{d.classList.remove('open');d.querySelector('button').setAttribute('aria-expanded','false')});b.parentElement.classList.toggle('open',open);b.setAttribute('aria-expanded',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('.drop').forEach(d=>{d.classList.remove('open');d.querySelector('button').setAttribute('aria-expanded','false')});document.querySelector('#nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}});
document.addEventListener('click',e=>{if(!e.target.closest('.drop'))document.querySelectorAll('.drop').forEach(d=>{d.classList.remove('open');d.querySelector('button').setAttribute('aria-expanded','false')})});

